-- 032: Fuel filter guides for the Mk5 GTI (FSI + TSI, one shared guide), the Mk5 R32, and the Mk7 GTI (in-tank, not a service item).
-- Task rows go in first: guides.id has a foreign key to tasks.id.
-- After running this, upload the four SVGs in illustrations/ to the 'illustrations' Storage bucket:
--   fuel-filter-hero.svg, fuel-filter-fittings.svg, r32-fuel-filter.svg, mk7-fuel-module.svg
-- No App.jsx or src/lib/data.js changes in this update (no new category).
begin;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('fuel-filter','bpy','fuel-filter','Fuel filter replacement','Engine','fuel system',array['fuel filter','fuel pressure regulator','P2293','P310B','1K0201051K']::text[],true,'45 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('fuel-filter-tsi','ccta','fuel-filter','Fuel filter replacement','Engine','fuel system',array['fuel filter','fuel pressure regulator','P2293','P310B','1K0201051K']::text[],true,'45 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('fuel-filter-r32','bub','fuel-filter-r32','Fuel filter replacement (R32)','Engine','fuel system',array['fuel filter','fuel pressure regulator','6Q0201051J','4 bar']::text[],true,'45 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('fuel-filter-mk7','cxca','fuel-filter-mk7','Fuel filter: in-tank, not a service item','Engine','fuel system',array['fuel filter','in-tank filter','fuel pump module','5Q0919051BK']::text[],true,'0 min',1) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('fuel-filter',$j${"id": "fuel-filter", "title": "Fuel filter replacement", "heroId": "fuel-filter-hero", "fits": "2006–2009 VW GTI · 2.0T FSI (BPY) and 2.0T TSI (CCTA/CBFA)", "alsoFits": "2005–2010 Jetta 2.0T · 2007–2015 Eos 2.0T · Mk6 GTI/Golf 2.0T · Audi A3 8P 2.0T · TT Mk2 2.0T (same filter, same underbody bracket)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–90", "risk": "Fuel on your hands and face · car on stands", "why": "On the 2.0T the fuel filter is also the low-pressure regulator: a spring-loaded valve in the canister holds the in-tank pump's output at 6.6 bar for the high-pressure pump on the engine. A clogged or tired one starves the HPFP, and the car tells you with P2293 or P310B before it ever leaves you stranded. FSI or TSI, it's the same canister in the same bracket.", "note": "FCP Euro's Mk5 procedure and Pelican Parts' article agree on every step. They differ only on whether to pull the fuel-pump fuse first."}, "heroCap": "Under the passenger side, just ahead of the rear wheel and tucked against the frame rail beside the tank. Two lines on the tank end (supply in, return out), one line on the engine end, one Phillips screw on the bracket.", "lifespan": {"title": "When to expect it", "headline": ["No factory interval for the gasoline cars. Vendors say 30,000–40,000 miles; owners mostly do it when they realise it has never been done"], "earliest": "Cars with debris in the tank can clog one early; the usual story is a used car at 100,000+ miles with the original filter", "detail": "The US maintenance schedule lists a fuel-filter change for the TDI only. Pelican quotes VW at 30,000 miles, Europa Parts and Deutsche Auto Parts at 40,000. One owner went fifteen years before misfires sent him under the car. Because the regulator is inside the filter, the first symptom is usually a low-pressure code rather than a stumble.", "factors": ["Unknown service history", "Codes P2293 or P310B with a healthy pump", "Bad fuel or a rusty tank", "An upgraded in-tank pump (the filter is the only thing between it and the HPFP)"], "inspect": ["There's nothing to inspect from outside. If it's original at 100k, replace it; it's a $30 part."], "confidence": {"level": "varies", "n": 4, "note": "Vendors disagree (30k vs 40k); the factory schedule is silent for gasoline engines. Owner practice clusters at 40–60k or 'whenever'."}}, "should": {"yesIf": ["You don't know when it was last done", "P2293 (fuel pressure regulator performance) or P310B (low-pressure regulation) with no other obvious cause", "You're replacing the in-tank pump or its controller anyway", "Long cranks or hesitation under load after the usual suspects (plugs, coils, cam follower) check out"], "codes": ["P2293", "P310B", "P0087"], "notes": ["The filter is the cheapest thing in the low-pressure chain. Pelican's tech answers to P310B owners are always the same: replace the filter, then test pressure and volume from the in-tank pump before buying a high-pressure pump.", "It has to be the 6.6-bar filter. The 4-bar canister (6Q0 201 051 J) that fits the same bracket is for the 2.5 and the R32's VR6; on a 2.0T it will hold the wrong low-side pressure. APR's Mike put it plainly on VWVortex: 6.4 bar for the 2.0 FSI, 4 bar for the 2.0 non-turbo and 2.5. VW has since revised the FSI/TSI part to 6.6 bar."], "confidence": {"level": "high", "n": 5, "note": "Procedure agrees across FCP Euro, Pelican and two forum DIYs; the pressure-rating point is settled by VW's own supersession and a vendor engineer."}}, "parts": [{"tier": "oe", "name": "Fuel filter with 6.6-bar regulator, Genuine VW", "pn": "1K0 201 051 K (supersedes 1K0 201 051 C)", "note": "Same part for FSI and TSI. The K is the current revision; C is the older 6.4-bar version. Both work; buy the K if you're choosing.", "price": "$80–90", "links": [{"store": "ECS Tuning (Genuine)", "url": "https://www.ecstuning.com/b-genuine-volkswagen-audi-parts/fuel-filter/1k0201051k/"}, {"store": "Deutsche Auto Parts", "url": "https://www.shopdap.com/1k0-201-051-k.html"}]}, {"tier": "oem", "name": "Fuel filter, Mann WK 69 / Hengst H280WK / Mahle KL 572", "pn": "cross to 1K0 201 051 K", "note": "Same filter and regulator in a maker's box. Confirm the box says 6.6 bar (or 6.4).", "price": "$30–45", "links": [{"store": "FCP Euro (Mann)", "url": "https://www.fcpeuro.com/products/audi-vw-fuel-filter-1k0201051cmn"}, {"store": "ECS Tuning (Hengst)", "url": "https://www.ecstuning.com/b-hengst-parts/fuel-filter/1k0201051k~hen/"}, {"store": "ECS Tuning (Mahle)", "url": "https://www.ecstuning.com/b-mahle-parts/fuel-filter/1k0201051k~mah/"}]}], "aftermarket": [{"name": "Unbranded 'fits 1K0201051B/C/K' filters", "note": "Marketplaces sell one canister under all three part numbers, which is exactly the 4-bar / 6.6-bar confusion you're trying to avoid. The regulator rating is stamped on the housing; if the listing can't tell you which one you're getting, buy from a parts house that can.", "price": "$10–20", "signal": "Community verdict: not worth the gamble on a regulator", "links": []}], "tools": [{"name": "Phillips screwdriver"}, {"name": "Floor jack and two jack stands"}, {"name": "17mm socket and breaker bar", "note": "Only if you take the rear wheel off for room (FCP does; Pelican doesn't)"}, {"name": "Fuse puller (there's one in the fuse-panel lid) or small pliers"}, {"name": "Drain pan, rags, nitrile gloves, safety glasses"}], "before": ["Work outdoors or with the garage door open. No incandescent work lights, no power tools near the open lines, nobody smoking.", "Run the tank down if you can; less fuel means less weight in the lines and less to catch.", "Have the new filter out of the box and read the stamp on it: 6.6 bar (or 6.4). If it says 4 bar, stop; wrong part."], "steps": [{"n": 1, "title": "Take the pressure out of the lines", "blocks": [{"t": "text", "b": "Open the fuse panel on the driver's end of the dash (pop the cover with the tip of the key). Pull the fuel-pump fuse, then start the engine: it runs a few seconds and dies. Crank once more to be sure. Pelican and the VWVortex DIY both do this; the fuse number varies by year and market, so use the chart in your owner's manual or on the panel lid rather than trusting a forum post. Then pop the gas cap to vent the tank."}, {"t": "note", "b": "FCP Euro skips the fuse and simply disconnects the battery, accepting a few tablespoons of fuel when the lines come off. Either way works. The fuse method means less fuel in your face; the battery method means no hunting for a fuse. Don't do neither."}]}, {"n": 2, "title": "Passenger side up, find the filter", "blocks": [{"t": "text", "b": "Jack the rear passenger side and set it on stands (both rear stands if you're going under). Pull the wheel if you want room; FCP does, Pelican works around it. Look up between the tank and the frame rail, just ahead of the wheel: a canister about the size of a soda can, clipped into a plastic bracket, with two lines on the rear end and one on the front."}, {"t": "ill", "id": "fuel-filter-hero", "cap": "Plan view from below. Tank end: supply from the pump and return to the tank. Engine end: the single line to the high-pressure pump. The Phillips screw is on the bracket's clamp."}]}, {"n": 3, "title": "Tank-end lines off", "caution": true, "blocks": [{"t": "text", "b": "Drain pan under the filter. Each line ends in a quick-connect collar with two plastic tabs. Squeeze both tabs and pull the collar straight off the filter's nipple. If one is stuck, push the line a little further on first, wiggle, then pull; Pelican's tip. Do the two lines on the tank end first: they're the easy ones."}, {"t": "warn", "b": "Fuel will still be present. Expect a few tablespoons when the lines come off, more from the blue line. Keep your face out of the line of fire and have the rags ready."}, {"t": "ill", "id": "fuel-filter-fittings", "cap": "Squeeze both tabs on the collar and pull. The pin on the new filter indexes to a tab on the bracket, and the arrow on the housing points toward the engine."}]}, {"n": 4, "title": "Bracket screw, then the engine-end line", "blocks": [{"t": "text", "b": "Undo the single Phillips screw on the bracket clamp and fold the plastic strap down. With the tank-end lines off, the filter can now rotate in the bracket, which is how you get at the front line's tabs (FCP's trick: the front fitting is tight against the body until you turn the canister). Squeeze, pull, and the old filter is out."}]}, {"n": 5, "title": "New filter in, pointing the right way", "blocks": [{"t": "text", "b": "The filter flows one way, tank to engine. The housing carries an arrow and a moulded pin; the pin drops into a tab on the bracket so the filter can only sit one way (FCP). Seat it, fold the strap up, snug the Phillips screw: it's a plastic clamp, don't crank it. Push each line onto its nipple until the collar clicks; tug each one to prove it."}]}, {"n": 6, "title": "Prime and check", "blocks": [{"t": "text", "b": "Fuse back in (or battery on), gas cap on. Turn the key to run without cranking, wait five seconds, off, and repeat two or three times so the pump refills the lines. Start it. It may stumble once. Get under the car with a light and watch all three fittings for a minute while it idles; a weep now is a fitting that isn't clicked home."}, {"t": "note", "b": "No bleeding. Pelican's answer to a 2008 TSI owner whose car wouldn't start after the swap: it primes itself; if it won't, the new filter is in backwards or blocked."}, {"t": "embed", "id": "le_2VTjpR0U", "title": "FCP Euro: pump, controller and filter on a Mk5 GTI", "note": "The filter is the last part of the video (their step 5). Same technique for the quick-connects as on the pump housing."}]}], "alsoReplace": [{"name": "Fuel pump control module (under the rear seat)", "why": "If you came here for P310B and the filter didn't clear it, this is the next cheapest link. FCP replaces pump, controller and filter together on a car with codes."}, {"name": "Rear brake pads and rotors: look, at least", "why": "The wheel's off and you're on the ground. Ten seconds with a light."}], "check": {"tab": "Read the old filter", "title": "What the old filter tells you", "illId": "fuel-filter-fittings", "illCap": "Tip the old canister into a clear jar before you bin it.", "rows": [{"see": "Fuel pours out clean and clear", "means": "The filter was fine; the tank is clean.", "do": "Nothing more. If you had codes, they're not the filter."}, {"see": "Dark fuel, rust or grit in the jar", "means": "The filter was doing its job and the tank is dirty.", "do": "Plan on the in-tank pump's strainer sooner rather than later, and don't run the tank to empty."}, {"see": "Codes come straight back after the swap", "means": "Filter wasn't the restriction.", "do": "Test pressure and volume from the in-tank pump before buying an HPFP (Pelican's standing advice)."}], "c": {"level": "community", "n": 3, "note": "Pelican tech replies and forum experience; no factory diagnostic tree in this pass."}}, "aftercare": ["Check the three fittings again after the first drive.", "Note mileage and the part number (K or C) somewhere you'll find it.", "If you have an upgraded in-tank pump, do the filter more often; it's the only filtration before the HPFP."], "disagreements": [{"topic": "Pull the fuse or not?", "pos": "Pelican and the VWVortex DIY pull the fuel-pump fuse and crank until it stalls. FCP disconnects the battery and catches the fuel.", "call": "Pull the fuse if you can find it in your manual; otherwise the battery. Both are fine."}, {"topic": "4 bar or 6.4/6.6 bar?", "pos": "One owner's Bentley table says 4 bar. APR's engineer and VW's own supersession say 6.4, revised to 6.6, for the 2.0T.", "call": "6.6 bar (1K0 201 051 K). The 4-bar filter is for the 2.5 and the R32."}, {"topic": "Interval", "pos": "Pelican quotes VW at 30,000 miles; Europa and DAP say 40,000; the US gasoline schedule lists nothing.", "call": "40,000, or now if you don't know."}, {"topic": "Wheel off?", "pos": "FCP removes it for room; Pelican and the forum DIYs don't.", "call": "Take it off. It's four bolts and the front fitting is fiddly."}], "sources": ["Pelican Parts, 'Volkswagen Golf GTI Mk V Fuel Filter Replacement (2006–2009)'", "FCP Euro blog and video, 'How To Replace A Volkswagen/Audi Fuel Pump Controller, Fuel Pump, And Fuel Filter' (2020)", "VWVortex, '4 bar vs 6.4 bar fuel filter?' (APR reply)", "VWVortex, 'DIY – Fuel filter' (2025)", "VWVortex, 'Fuel filter replacement interval? Never?' (owner reading of the maintenance schedule)", "Deutsche Auto Parts and ECS Tuning listings for 1K0 201 051 K (supersession and regulator rating)", "VW parts catalog (parts.vw.com) fitment for 1K0 201 051 K and 6Q0 201 051 J"], "embeds": [{"id": "le_2VTjpR0U", "note": "FCP Euro, 2020. Pump and controller first; the filter is step 5."}, {"id": "DXp8itbUh9k", "note": "Owner how-to, 2016: filter only, on a Mk5. Shows the fitting tabs well."}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('fuel-filter-r32',$j${"id": "fuel-filter-r32", "title": "Fuel filter replacement (R32)", "heroId": "r32-fuel-filter", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · 4Motion", "alsoFits": "Mk5 Rabbit/Jetta 2.5 · Audi A3 8P 3.2 quattro · TT Mk2 3.2 (same 4-bar filter and bracket)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$25–70", "risk": "Fuel on your hands and face · car on stands · driveshaft down the middle", "why": "Same bracket, same three quick-connects, same Phillips screw as the GTI next to it in the showroom, and a different filter. The VR6 is port-injected and runs its rail at 4 bar, so its filter carries a 4-bar regulator. Put the GTI's 6.6-bar canister on it and the injectors see pressure they weren't calibrated for.", "note": "No R32-specific write-up exists; the procedure is the Mk5 chassis procedure from FCP Euro and Pelican, with the part number from VW's catalog and ECS's R32 listing."}, "heroCap": "Passenger side, ahead of the rear wheel, against the frame rail beside the tank. The 4Motion driveshaft runs down the tunnel and the Haldex sits behind the rear axle; neither is in your way, but keep your jack and stands on the sills, not the tunnel.", "lifespan": {"title": "When to expect it", "headline": ["No factory interval. Europa Parts says 40,000 miles; most R32s are on their original filter"], "earliest": null, "detail": "The gasoline Mk5 schedule doesn't list a fuel filter. Unlike the 2.0T, the VR6 has no low-pressure fuel sensor to throw a code when the filter tires, so it shows up as hesitation at full throttle or a long crank after sitting, if it shows up at all. On a car this age with unknown history, do it once and forget it.", "factors": ["Unknown history", "Hesitation or a lean stumble at high load", "Bad fuel", "Any time the in-tank pump comes out"], "inspect": ["Nothing to inspect from outside; replace on history."], "confidence": {"level": "community", "n": 3, "note": "Vendor interval and Mk5-chassis owner practice. The 'no low-pressure sensor' point is from the FSI/VR6 fuel-system difference, not a factory wiring diagram."}}, "should": {"yesIf": ["Original filter on a car with 100,000+ miles", "Full-throttle hesitation once fuel, plugs and coils are ruled in", "You're servicing the in-tank pump", "You just bought it"], "codes": [], "notes": ["Buy the 4-bar filter: 6Q0 201 051 J, which is what VW's catalog lists for the R32 and what ECS's R32 catalog stocks. Some retailers list the GTI's 6.4/6.6-bar 1K0 201 051 K as fitting the Mk5 R32 because the bracket and fittings are identical. Fit is not the same as function; the number stamped on the housing must say 4 bar.", "Everything else about the job is the GTI job. If you've done a Mk5 GTI filter, you've done this."], "confidence": {"level": "medium", "n": 3, "note": "Part number from VW's catalog and ECS; procedure from the Mk5-chassis guides. No R32-only first-hand write-up found this pass."}}, "parts": [{"tier": "oe", "name": "Fuel filter with 4-bar regulator, Genuine VW", "pn": "6Q0 201 051 J (supersedes 6Q0 201 051 A / C)", "note": "The R32 and 2.5-litre filter. Stamped 4 bar.", "price": "$60–70", "links": [{"store": "ECS Tuning (Genuine)", "url": "https://www.ecstuning.com/b-genuine-volkswagen-audi-parts/fuel-filter/6q0201051j/"}, {"store": "Europa Parts", "url": "https://www.europaparts.com/fuel-filter-6q0201051j.html"}]}, {"tier": "oem", "name": "Fuel filter, Mann / Hengst / Mahle / Meyle", "pn": "cross to 6Q0 201 051 J", "note": "Hengst is ECS's preferred OE supplier here. Check the housing says 4 bar before it goes on.", "price": "$25–50", "links": [{"store": "ECS Tuning (Hengst)", "url": "https://www.ecstuning.com/b-hengst-parts/fuel-filter/6q0201051j~hen/"}, {"store": "ECS Tuning (Mann)", "url": "https://www.ecstuning.com/b-mann-parts/fuel-filter/6q0201051j~mankt/"}, {"store": "ECS Tuning (Mahle)", "url": "https://www.ecstuning.com/b-mahle-parts/fuel-filter/6q0201051j~mah/"}]}], "aftermarket": [{"name": "Inline high-flow filters (Precision Raceworks AN8 and similar)", "note": "ECS lists these under the R32 because turbo-kit builders plumb them in. On a stock or naturally-aspirated VR6 they solve nothing; the factory canister already carries the regulator you need.", "price": "$150–170", "signal": "Community verdict: turbo builds only", "links": []}], "tools": [{"name": "Phillips screwdriver"}, {"name": "Floor jack and two jack stands"}, {"name": "17mm socket and breaker bar", "note": "If you pull the rear wheel for room"}, {"name": "Fuse puller or small pliers"}, {"name": "Drain pan, rags, nitrile gloves, safety glasses"}], "before": ["Outdoors or door open; no incandescent lights or power tools near open fuel lines.", "Read the stamp on the new filter: 4 bar. If it says 6.4 or 6.6, it's the GTI part.", "Run the tank down if you can."], "steps": [{"n": 1, "title": "Take the pressure out of the lines", "blocks": [{"t": "text", "b": "Fuse panel on the driver's end of the dash: pull the fuel-pump fuse, start the car, let it stall, crank once more. Use the chart in your manual for the fuse position (the Mk4 R32 DIYs say #28; the Mk5 panel is laid out differently, so check). Pop the gas cap."}, {"t": "note", "b": "Or disconnect the battery and catch the fuel, as FCP Euro does on the Mk5. Either, not neither."}]}, {"n": 2, "title": "Passenger side up, find the filter", "blocks": [{"t": "text", "b": "Rear passenger side on stands; wheel off for room. The filter is a canister in a plastic bracket between the tank and the frame rail, just ahead of the wheel: two lines on the tank end, one on the engine end. On the 4Motion car the driveshaft and the Haldex unit are nearby but not in your way; jack on the sill points, never on the tunnel or the rear differential."}, {"t": "ill", "id": "r32-fuel-filter", "cap": "From below: the 4Motion driveshaft down the tunnel, the Haldex coupling and rear differential behind the axle, and the filter in the same right-side bracket the GTI uses. The canister is stamped 4 bar."}]}, {"n": 3, "title": "Tank-end lines off", "caution": true, "blocks": [{"t": "text", "b": "Drain pan under the filter. Squeeze the two tabs on each quick-connect collar and pull straight off. Stuck one: push on a little, wiggle, pull. Tank end first."}, {"t": "warn", "b": "Fuel comes out. A few tablespoons, more if you skipped the fuse. Face out of the way, rags ready."}, {"t": "ill", "id": "fuel-filter-fittings", "cap": "Same fittings as every Mk5: squeeze both tabs, pull. Pin to bracket tab, arrow toward the engine."}]}, {"n": 4, "title": "Bracket screw, then the engine-end line", "blocks": [{"t": "text", "b": "One Phillips screw on the bracket clamp; fold the strap down. Rotate the freed canister to bring the front fitting's tabs where you can reach them, squeeze, pull, and it's out."}]}, {"n": 5, "title": "New 4-bar filter in", "blocks": [{"t": "text", "b": "Arrow toward the engine, moulded pin into the bracket tab. Strap up, screw snug (plastic clamp). Click each line home and tug it."}]}, {"n": 6, "title": "Prime and check", "blocks": [{"t": "text", "b": "Fuse in or battery on, cap on. Key to run without cranking, five seconds, off; three times. Start it, then watch the three fittings under a light while it idles. Take it for a hard pull and listen for the hesitation you came to fix."}, {"t": "embed", "id": "le_2VTjpR0U", "title": "FCP Euro: the Mk5-chassis filter swap", "note": "A GTI, but the bracket, screw and quick-connects are the ones on your car. Filter is their step 5."}]}], "alsoReplace": [{"name": "Haldex fluid and filter", "why": "You're under the back of the car anyway and it's the R32 service everyone forgets. It's a separate guide in this category's neighbour, Drivetrain."}, {"name": "Rear brake pads and rotors: look", "why": "Wheel's off. Ten seconds."}], "check": {"tab": "Read the old filter", "title": "What the old filter tells you", "illId": "fuel-filter-fittings", "illCap": "Tip the old canister into a clear jar before you bin it.", "rows": [{"see": "Clean, clear fuel", "means": "Filter was fine, tank is clean.", "do": "Nothing more."}, {"see": "Dark fuel, rust or grit", "means": "Tank is dirty; the filter was earning its keep.", "do": "Plan on the in-tank pump strainer; don't run the tank low."}, {"see": "Hesitation persists", "means": "Not the filter.", "do": "Fuel pressure test at the rail (4 bar expected), then pump volume."}], "c": {"level": "community", "n": 2, "note": "Mk5-chassis owner experience; no factory diagnostic tree for the VR6 in this pass."}}, "aftercare": ["Check the fittings after the first drive.", "Note mileage and part number."], "disagreements": [{"topic": "Which filter?", "pos": "VW's catalog and ECS's R32 listing: 6Q0 201 051 J, 4 bar. NGP and some marketplace listings: the 2.0T's 6.4/6.6-bar 1K0 201 051 C/K 'fits the Mk5 R32'.", "call": "4 bar. Fitting the bracket isn't the point; the regulator is."}, {"topic": "Fuse position", "pos": "Mk4 R32 write-ups say fuse #28; Mk5 sources say check the manual.", "call": "Check the manual, or use the battery method."}], "sources": ["VW parts catalog (parts.vw.com) and dealer R32 listings for 6Q0 201 051 J ('GTI; 4 bar', R32)", "ECS Tuning, Volkswagen R32 MKV 3.2 fuel filter catalog (Genuine, Hengst, Mann, Mahle, Meyle 6Q0 201 051 J)", "Europa Parts 6Q0 201 051 J listing (40,000-mile recommendation)", "FCP Euro Mk5 fuel filter procedure (2020)", "Pelican Parts Mk5 fuel filter article", "VWVortex, '4 bar vs 6.4 bar fuel filter?' (which engines take which)", "Autodoc procedures for Golf V 4motion and A3 8PA 3.2 quattro (same bracket and screw)"], "embeds": [{"id": "le_2VTjpR0U", "note": "FCP Euro on a Mk5 GTI. Same bracket and fittings as the R32."}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('fuel-filter-mk7',$j${"id": "fuel-filter-mk7", "title": "Fuel filter: in-tank, not a service item", "heroId": "mk7-fuel-module", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "alsoFits": "Every MQB gasoline Golf, Golf R, Jetta, Audi A3/S3 8V (same in-tank arrangement)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "0 min", "timeRepeat": "0 min", "difficulty": 1, "cost": "$0 (filter) · $300–500 if the pump module is replaced", "risk": "None, because there is nothing to do", "why": "There is no fuel filter under a Mk7. VW moved it inside the tank, built into the low-pressure pump module, and left it off the maintenance schedule. If you go looking for the Mk5/Mk6 canister on the frame rail you'll find bare floor. This guide exists so you stop looking and know what actually changes when the filter does.", "note": "Two owner forums, a dealer's parts schematic and the GTI maintenance schedule all say the same thing. No vendor sells a Mk7 gasoline fuel filter because there isn't one."}, "heroCap": "Section through the rear seat: the low-pressure pump module sits in the tank under the passenger-side access cover, with the filter element built into the module. The underbody position where a Mk5 or Mk6 carries a canister is empty.", "lifespan": {"title": "When to expect it", "headline": ["Never, as a scheduled item. It's replaced with the pump module, typically well past 100,000 miles"], "earliest": "2015–2016 cars had a recall on the tank's suction-jet pump (fire risk); that's a different part, but check your VIN's recall history", "detail": "The GTI maintenance schedule lists no fuel-filter service for gasoline engines. A dealer showed a 2015 owner the blow-up drawing with the filter inside the pump assembly and told him not to bother until the pump itself needs doing. VWVortex's resident tech agreed: with decent fuel, in-tank gasoline filters routinely pass 100,000 miles.", "factors": ["Repeated bad fuel or a contaminated tank", "Low-pressure codes with long cranks", "An owner who insists"], "inspect": ["Nothing. There's no filter to look at without pulling the pump."], "confidence": {"level": "high", "n": 4, "note": "Maintenance schedule, dealer schematic and two forum threads agree; the recall note is from one repair-shop source and should be checked against your VIN."}}, "should": {"yesIf": ["You have low-pressure fuel codes and long cranks and the in-tank pump is the diagnosis", "The pump module is out for any other reason"], "codes": [], "notes": ["Don't pay for a 'fuel filter service' on a Mk7 gasoline car. It either isn't happening or it's a pump module replacement being described oddly. A dealer quoted one owner about CA$500 for the module.", "One VWVortex poster suggested splicing an external serviceable filter into the line for peace of mind. Nobody took him up on it; the consensus was that VW engineered the car this way and it's fine. Filed here as an idea, not a recommendation.", "The TDI is different: it has a filter in the engine bay on a 20,000-mile interval. If someone tells you their Golf's fuel filter is due, that's the diesel."], "confidence": {"level": "high", "n": 4, "note": "Consistent across the maintenance schedule, a dealer, and two forums (VWVortex 2016, GolfMK7 2015)."}}, "parts": [{"tier": "oe", "name": "Low-pressure fuel pump module (filter integrated), Genuine VW", "pn": "5Q0 919 051 BK (as quoted on VWVortex; confirm against your VIN)", "note": "This is the only way the filter gets replaced. It's the pump, the level sender and the filter as one assembly.", "price": "$300–500 installed at a dealer (owner quote)", "links": []}], "aftermarket": [{"name": "External inline filter added to the feed line", "note": "A forum suggestion, not a product for this car. It adds two joints to a fuel line to solve a problem the maintenance schedule says you don't have.", "price": "—", "signal": "Community verdict: leave it", "links": []}], "tools": [{"name": "None for the filter itself"}, {"name": "For the pump module: trim tools, hammer and drift for the lock ring, rags, and an afternoon", "note": "That's a separate job and a separate guide when it's written"}], "before": ["If you're here because of codes, pull them and note freeze-frame fuel pressure before touching anything.", "Check your VIN for open recalls; 2015–2016 cars had a fuel-tank suction-pump campaign."], "steps": [{"n": 1, "title": "Confirm there's nothing under the car", "blocks": [{"t": "text", "b": "On a Mk5 or Mk6 the filter canister sits in a bracket on the passenger frame rail ahead of the rear wheel. On the Mk7 that spot is empty; the low-pressure line runs straight from the tank to the engine. If you've been told to change the fuel filter on a gasoline Mk7, this is where the conversation should have ended."}, {"t": "ill", "id": "mk7-fuel-module", "cap": "Where the Mk5/Mk6 canister would be, there's floor. The filter is inside the pump module under the rear seat."}]}, {"n": 2, "title": "Where it actually lives", "blocks": [{"t": "text", "b": "Lift the rear seat base and the passenger-side carpet flap and you'll find the round access cover over the tank. Under it is the low-pressure pump module: pump, level sender, and the filter element, sealed as one unit with a large plastic lock ring. That's the part VW's schematic labels as the fuel filter."}]}, {"n": 3, "title": "When it does get changed", "blocks": [{"t": "text", "b": "With the pump. Symptoms that point there are long cranks after sitting, low-pressure fuel codes, or a pump that's audibly straining. The swap itself is the same shape as the Mk5's in-tank pump job: fuse out, cover off, lock ring, hoses, module out through the hole. It isn't in this guide because you shouldn't need it as maintenance."}, {"t": "note", "b": "Owner thread consensus, 2015–2016: leave it alone. The one thing to act on is the suction-jet pump recall for early cars; check your VIN."}]}], "alsoReplace": [], "check": {"tab": "Is it the pump?", "title": "Reading the symptoms", "illId": "mk7-fuel-module", "illCap": "Everything fuel-related on the low-pressure side is in one module.", "rows": [{"see": "Someone quoted you a 'fuel filter change'", "means": "Gasoline Mk7: no such service.", "do": "Ask what part number they intend to fit. If it's a TDI filter, it's the wrong car."}, {"see": "Long cranks after sitting, low-pressure codes", "means": "Pump module suspect.", "do": "Fuel pressure and volume test first; module replacement if it fails."}, {"see": "Rough running, misfires, no fuel-pressure codes", "means": "Almost never the filter on this car.", "do": "Plugs, coils, PCV, carbon buildup: the usual Gen 3 list."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus a dealer's account; no factory diagnostic tree in this pass."}}, "aftercare": ["Nothing. Note in your records that the Mk7 has no serviceable fuel filter so the next owner doesn't go looking either."], "disagreements": [{"topic": "Does it ever need changing?", "pos": "One dealer told an owner 40,000 miles; the same owner's maintenance schedule and another dealer's schematic say it's part of the pump with no interval.", "call": "No interval. If a service writer says 40k, ask which part."}, {"topic": "Add an external filter?", "pos": "Suggested once on VWVortex; nobody endorsed it.", "call": "Don't."}], "sources": ["VWVortex, 'Fuel filter replacement interval? Never?' (2016): in-tank filter, part of 5Q0 919 051 BK, no external filter on the Mk7", "GolfMK7 forum, 'Fuel Filter change' (2015): filter is part of the LP pump under the rear seat; no interval in the GTI maintenance schedule", "Deutsche Auto Parts Mk7.5 GTI service schedule (no fuel filter listed)", "Griffin's Auto Repair, Golf/GTI common repairs (2015–2016 suction-pump recall note)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
commit;
